action.code:
if (internal_key.size() < 8) {
    return false;
  }
  uint64_t num = DecodeFixed64(internal_key.data() + internal_key.size() - 8);
  uint64_t seq = num >> 8;
  uint8_t t = num & 0xff;
  if (seq > kMaxSequenceNumber || t > kValueTypeForSeek) {
    return false;
  }
  *user_key = Slice(internal_key.data(), internal_key.size() - 8);
  *sequence = seq;
  *type = t;
  return true;

